const dialog=document.querySelector('#search-dialog'),input=document.querySelector('#search-input'),results=document.querySelector('#search-results'),status=document.querySelector('.search-status');
const openSearch=()=>{dialog.showModal();input.focus();};
document.querySelector('.search-trigger').addEventListener('click',openSearch);
document.querySelector('.search-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();openSearch();}if(e.key==='Escape')closeMenu();});
input.addEventListener('input',()=>{const query=input.value.trim().toLowerCase();results.replaceChildren();if(!query){status.textContent='Search definitions, chapters, and homework.';return;}const terms=query.split(/\s+/);const matches=(window.BOOK_INDEX||[]).map(p=>{const hay=(p.title+' '+p.text).toLowerCase();return {...p,score:terms.reduce((s,t)=>s+(p.title.toLowerCase().includes(t)?6:0)+(hay.includes(t)?1:0),0),match:terms.every(t=>hay.includes(t))};}).filter(p=>p.match).sort((a,b)=>b.score-a.score).slice(0,20);status.textContent=matches.length?`${matches.length} matching chapters`:'No matching chapters. Try a shorter phrase, such as scope or HW1.';for(const p of matches){const a=document.createElement('a');a.className='search-result';a.href=p.url;const small=document.createElement('small');small.textContent=p.part;const title=document.createElement('strong');title.textContent=p.title;const text=document.createElement('p');const at=p.text.toLowerCase().indexOf(terms[0]);text.textContent=(at>70?'…':'')+p.text.slice(Math.max(0,at-70),Math.max(0,at-70)+220)+'…';a.append(small,document.createElement('br'),title,text);results.append(a);}});
const menu=document.querySelector('.menu-toggle'),sidebar=document.querySelector('#sidebar');
function closeMenu(){sidebar.classList.remove('open');menu.setAttribute('aria-expanded','false');}
menu.addEventListener('click',()=>{const on=sidebar.classList.toggle('open');menu.setAttribute('aria-expanded',String(on));});
document.querySelector('main').addEventListener('click',closeMenu);
document.querySelector('.print-button').addEventListener('click',()=>window.print());
document.querySelectorAll('article table').forEach(t=>{const wrap=document.createElement('div');wrap.className='table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Scrollable table');t.before(wrap);wrap.append(t);});
const active=document.querySelector('.sidebar [aria-current]');if(active)sidebar.scrollTop=Math.max(0,active.offsetTop-sidebar.clientHeight/2);
const traces={
 closure:[['x ↦ 10','Evaluate the first binding. The current environment associates x with 10.'],['f ↦ Closure(y, x + y, {x ↦ 10})','Creating a function packages its parameter, body, and definition environment. The body is not run yet.'],['caller: x ↦ 90\nf still captures: x ↦ 10','A later binding shadows x in the caller. It does not replace the environment saved in f.'],['call f 3\nbody environment: y ↦ 3, x ↦ 10','Evaluate the argument in the caller, then extend the captured environment with the parameter.'],['x + y = 10 + 3 = 13','The lexical-scope result is 13. A dynamic-scope interpreter would incorrectly use the caller’s x here.']],
 store:[['environment: x ↦ ℓ0\nmemory: ℓ0 ↦ 4','A variable name denotes a location; the store supplies the current value.'],['evaluate x + 2\nlookup x → ℓ0 → 4\nresult: 6','Read through the environment and then the store.'],['x := 6\nenvironment: x ↦ ℓ0\nmemory: ℓ0 ↦ 6','Assignment updates memory at the existing location. The environment mapping stays the same.'],['evaluate x\nresult: 6\nfinal memory: ℓ0 ↦ 6','Sequence passes the updated memory to the next expression. In B, assignment itself also returns 6.']],
 unify:[['fun f -> fun x -> f (x + 1)\nf : α, x : β, result : γ','Assign fresh unknown types before looking at the operations.'],['x + 1 requires β = int\nx + 1 has type int','Arithmetic contributes a constraint; no program evaluation is needed.'],['f (x + 1) requires α = int → γ','A call connects the argument type to the function’s domain.'],['S = { β ↦ int, α ↦ int → γ }','Solve the equations and apply the substitution throughout the provisional type.'],['(int → γ) → int → γ','The result γ remains unconstrained. This is the most general monomorphic type, up to variable names.']],
 exception:[['try (5 + (raise 9)) catch x (x + 2)\nk = End','Begin with no pending outer computation. This is the course toy language, not OCaml syntax.'],['k = AddLeft(5) :: Handler(x, x+2) :: End','After evaluating 5, the addition waits for its right operand. The handler remains below it.'],['raise 9\ndiscard AddLeft(5)','Raising abandons the pending addition while searching for the nearest handler.'],['handler environment: x ↦ 9\nk = End','Run the handler in its saved environment, extended with the payload. The handler frame itself is removed.'],['9 + 2 = 11','The answer is 11, not 16: the abandoned addition is never resumed.']]
};
document.querySelectorAll('[data-trace]').forEach(box=>{const steps=traces[box.dataset.trace];if(!steps)return;let i=0;const title=document.createElement('h3');title.textContent=box.dataset.title||'Walk through the evaluation';const state=document.createElement('div');state.className='trace-state';const note=document.createElement('p');note.className='trace-note';const region=document.createElement('div');region.setAttribute('aria-live','polite');region.append(state,note);const controls=document.createElement('div');controls.className='trace-controls';const back=document.createElement('button'),next=document.createElement('button'),reset=document.createElement('button'),count=document.createElement('span');back.textContent='← Back';next.textContent='Next step →';reset.textContent='Reset';count.className='trace-count';controls.append(back,next,reset,count);const draw=()=>{state.textContent=steps[i][0];note.textContent=steps[i][1];count.textContent=`${i+1} / ${steps.length}`;back.disabled=i===0;next.disabled=i===steps.length-1;};back.onclick=()=>{i--;draw();};next.onclick=()=>{i++;draw();};reset.onclick=()=>{i=0;draw();};box.replaceChildren(title,region,controls);draw();});
